out<-'tmp/advanced-planning-i18n';dir.create(out,recursive=TRUE,showWarnings=FALSE)
stopifnot(requireNamespace('WebPower',quietly=TRUE))
base<-function(m){v<-list(target='sample_size',alpha='0.05',power='0.8',n='120',ratio='1',alternative='two.sided',dropout='0');setNames(v,paste0('sample_size_',m,'_',names(v)))}
cinput<-modifyList(base('cluster'),list(sample_size_cluster_design='parallel',sample_size_cluster_outcome='continuous',sample_size_cluster_effect='0.5',sample_size_cluster_p1='0.5',sample_size_cluster_p2='0.65',sample_size_cluster_size='10',sample_size_cluster_icc='0.05',sample_size_cluster_periods='4',sample_size_cluster_simulations='20'))
rinput<-modifyList(base('reliability'),list(sample_size_reliability_value='0.8',sample_size_reliability_confidence='0.95',sample_size_reliability_half_width='0.1',sample_size_reliability_items='5',sample_size_reliability_categories='2'))
sinput<-modifyList(base('sem'),list(sample_size_sem_test='close_fit',sample_size_sem_df_source='manual',sample_size_sem_df='20',sample_size_sem_null_rmsea='0.05',sample_size_sem_alternative_rmsea='0.08',sample_size_sem_parameter_type='path',sample_size_sem_parameter='0.3',sample_size_sem_complexity='moderate',sample_size_sem_simulations='100',sample_size_sem_latent_variables='3',sample_size_sem_measured_variables='9',sample_size_sem_structural_paths='3',sample_size_sem_free_parameters='20',sample_size_sem_expected_loading='0.7',sample_size_sem_expected_path='0.3'))
results<-c(list(sample_size_calculate('cluster',modifyList(cinput,list(sample_size_cluster_design='stepped_wedge',sample_size_cluster_target='power',sample_size_cluster_n='12'))),sample_size_calculate('cluster',cinput),sample_size_calculate('cluster',modifyList(cinput,list(sample_size_cluster_outcome='binary')))),lapply(c('bland_altman','alpha','icc','kappa'),function(d)sample_size_calculate('reliability',modifyList(rinput,list(sample_size_reliability_design=d)))),list(sample_size_calculate('sem',modifyList(sinput,list(sample_size_sem_test='complexity'))),sample_size_calculate('sem',modifyList(sinput,list(sample_size_sem_test='parameter',sample_size_sem_target='power'))),sample_size_calculate('sem',sinput)))
designs<-c('cluster-stepped-power','cluster-WebPower','cluster-binary-DE','bland-altman','alpha','icc','kappa','sem-complexity','sem-parameter-power','sem-rmsea')
formula_keys<-paste0('sample_size.result.',c('planning_cluster_stepped','planning_cluster_webpower','planning_cluster_de','planning_reliability_ba','planning_reliability_alpha','planning_reliability_icc','planning_reliability_kappa','planning_sem_complexity','planning_sem_parameter','planning_sem_rmsea'))
for(i in seq_along(results))if(!is.null(results[[i]]$error)||!identical(results[[i]]$formula_note,statedu_t(formula_keys[i],'en')))stop('Unexpected result ',designs[i],': ',results[[i]]$error,' / ',results[[i]]$formula_note)
stopifnot(results[[2]]$engine=='WebPower',results[[4]]$total==ceiling((qnorm(.975)*sqrt(3)*.8/.1)^2))
for(i in c(1,9))stopifnot(is.finite(results[[i]]$power),results[[i]]$power>=0,results[[i]]$power<=1)
tokens<-list(planning_cluster_webpower='WebPower::wp.crt2arm',planning_cluster_de='DE = 1 + (m - 1) ICC',planning_reliability_alpha='log(1 - alpha)',planning_sem_rmsea='lambda = (N - 1) df RMSEA^2')
for(lang in c('en','ko','ja','zh','es','fr','de','vi'))for(key in names(tokens))stopifnot(grepl(tokens[[key]],statedu_t(paste0('sample_size.result.',key),lang),fixed=TRUE))
cat('PASS ten actual cluster/reliability/SEM branches, WebPower engine, agreement reference and eight-language tokens\n')
